        k2 = 0;

        result = asn1_number_of_elements(asn1_struct, tmpbuffer1, &max_k2);
        if (result != ASN1_SUCCESS) {
                gnutls_assert();
                result = _gnutls_asn2err(result);
                goto cleanup;
        }

